// FUNCTION: BFME2 0x0013CEA0 size=398 name=?Init_From_Material3@VertexMaterialClass@@QAEXABUW3dMaterial3Struct@@@Z evidence=N:ledger tier=A
void VertexMaterialClass::Init_From_Material3(const W3dMaterial3Struct &legacy)
{
	Vector3 color;
	Vector3 coeff;
	Vector3 result;

	Convert_Color(legacy.DiffuseColor, &color);
	Convert_Color(legacy.DiffuseCoefficients, &coeff);
	result.X = color.X * coeff.X;
	result.Y = color.Y * coeff.Y;
	result.Z = color.Z * coeff.Z;
	Set_Diffuse(result);

	Convert_Color(legacy.SpecularColor, &color);
	Convert_Color(legacy.SpecularCoefficients, &coeff);
	result.X = color.X * coeff.X;
	result.Y = color.Y * coeff.Y;
	result.Z = color.Z * coeff.Z;
	Set_Specular(result);

	Convert_Color(legacy.EmissiveCoefficients, &color);
	Set_Emissive(color);
	Convert_Color(legacy.AmbientCoefficients, &color);
	Set_Ambient(color);

	Set_Shininess(legacy.Shininess);
	Set_Opacity(legacy.Opacity);
}

// FUNCTION: BFME2 0x0013D030 size=327 name=?Parse_W3dVertexMaterialStruct@VertexMaterialClass@@QAEXABUW3dVertexMaterialStruct@@@Z evidence=N:ledger tier=A
void VertexMaterialClass::Parse_W3dVertexMaterialStruct(const W3dVertexMaterialStruct &record)
{
	Vector3 color;
	Convert_Color(record.Ambient, &color);
	Set_Ambient(color);
	Convert_Color(record.Diffuse, &color);
	Set_Diffuse(color);
	Convert_Color(record.Specular, &color);
	Set_Specular(color);
	Convert_Color(record.Emissive, &color);
	Set_Emissive(color);
	Set_Shininess(record.Shininess);
	Set_Opacity(record.Opacity);

	if (record.Attributes & W3DVERTMAT_USE_DEPTH_CUE)
		Set_Flag(DEPTH_CUE, true);
	if (record.Attributes & W3DVERTMAT_COPY_SPECULAR_TO_DIFFUSE)
		Set_Flag(COPY_SPECULAR_TO_DIFFUSE, true);
}

