// FUNCTION: BFME2 0x0013DC00 size=257 name=??4VertexMaterialClass@@QAEAAV0@ABV0@@Z evidence=N:ledger tier=A
VertexMaterialClass &VertexMaterialClass::operator=(const VertexMaterialClass &other)
{
	if (this != &other) {
		Name = other.Name;
		Flags = other.Flags;
		AmbientColorSource = other.AmbientColorSource;
		EmissiveColorSource = other.EmissiveColorSource;
		DiffuseColorSource = other.DiffuseColorSource;
		UseLighting = other.UseLighting;
		UniqueID = other.UniqueID;
		CRCDirty = other.CRCDirty;

		// Mappers are not shared: drop ours, then take clones of the other's.
		int stage;
		for (stage = 0; stage < MAX_STAGES; stage++) {
			if (Mapper[stage] != NULL) {
				Mapper[stage]->Release_Ref();
				Mapper[stage] = NULL;
			}
		}
		for (stage = 0; stage < MAX_STAGES; stage++) {
			if (other.Mapper[stage] != NULL) {
				TextureMapperClass *copy = other.Mapper[stage]->Clone();
				Set_Mapper(copy, stage);
				copy->Release_Ref();
			}
			UVSource[stage] = other.UVSource[stage];
		}
		*Material = *other.Material;
	}
	return *this;
}

